    (63, 'Challenger Model', 'Consumer - FWA Churn %', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SAFE_DIVIDE([Consumer - FWA Disconnects], [Consumer - FWA Average Connections])', TRUE),
    (64, 'Challenger Model', 'Business - FWA Churn %', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SAFE_DIVIDE([Business - FWA Disconnects], [Business - FWA Average Connections])', TRUE),
    (65, 'Challenger Model', 'Consumer - Fios Average Fiber Connections', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ROLLING_AVG([Consumer - Fios Fiber Connections], 2)', TRUE),
    (66, 'Challenger Model', 'Consumer - Frontier Average Fiber Connections', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ROLLING_AVG([Consumer - Frontier Fiber Connections], 2)', TRUE),
    (67, 'Challenger Model', 'Business - Fios Average Fiber Connections', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ROLLING_AVG([Business - Fios Fiber Connections], 2)', TRUE),
    (68, 'Challenger Model', 'Business - Frontier Average Fiber Connections', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ROLLING_AVG([Business - Frontier Fiber Connections], 2)', TRUE),
    (69, 'Challenger Model', 'Consumer - Fios Fiber Connections', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ROLL_FORWARD(connections=[Consumer - Fios Fiber Connections], net_adds=[Consumer - Fios Fiber Net Adds], adj=[Calculated Consumer - Fios Fiber Connections Adj])', TRUE),
    (70, 'Challenger Model', 'Consumer - Frontier Fiber Connections', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ROLL_FORWARD(connections=[Consumer - Frontier Fiber Connections], net_adds=[Consumer - Frontier Fiber Net Adds], adj=[Calculated Consumer - Frontier Fiber Connections Adj])', TRUE),
    (71, 'Challenger Model', 'Business - Fios Fiber Connections', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ROLL_FORWARD(connections=[Business - Fios Fiber Connections], net_adds=[Business - Fios Fiber Net Adds], adj=[Calculated Business - Fios Fiber Connections Adj])', TRUE),
    (72, 'Challenger Model', 'Business - Frontier Fiber Connections', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ROLL_FORWARD(connections=[Business - Frontier Fiber Connections], net_adds=[Business - Frontier Fiber Net Adds], adj=[Calculated Business - Frontier Fiber Connections Adj])', TRUE),
    (73, 'Challenger Model', 'Consumer - Fios Fiber Churn %', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SAFE_DIVIDE([Consumer - Fios Fiber Disconnects], [Consumer - Fios Average Fiber Connections])', TRUE),
    (74, 'Challenger Model', 'Consumer - Frontier Fiber Churn %', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SAFE_DIVIDE([Consumer - Frontier Fiber Disconnects], [Consumer - Frontier Average Fiber Connections])', TRUE),
    (75, 'Challenger Model', 'Business - Fios Fiber Churn %', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SAFE_DIVIDE([Business - Fios Fiber Disconnects], [Business - Fios Average Fiber Connections])', TRUE),
    (76, 'Challenger Model', 'Business - Frontier Fiber Churn %', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SAFE_DIVIDE([Business - Frontier Fiber Disconnects], [Business - Frontier Average Fiber Connections])', TRUE),
    (77, 'Challenger Model', 'Consumer - Fios Fiber Net Adds', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[Consumer - Fios Fiber Gross Adds] - [Consumer - Fios Fiber Disconnects]', TRUE),
    (78, 'Challenger Model', 'Consumer - Frontier Fiber Net Adds', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[Consumer - Frontier Fiber Gross Adds] - [Consumer - Frontier Fiber Disconnects]', TRUE),
    (79, 'Challenger Model', 'Business - Fios Fiber Net Adds', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[Business - Fios Fiber Gross Adds] - [Business - Fios Fiber Disconnects]', TRUE),
    (80, 'Challenger Model', 'Business - Frontier Fiber Net Adds', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[Business - Frontier Fiber Gross Adds] - [Business - Frontier Fiber Disconnects]', TRUE),
    (81, 'Challenger Model', 'Consumer - Phone Net Adds', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[Consumer - Phone Gross Adds] - [Consumer - Phone Disconnects]', TRUE),
    (82, 'Challenger Model', 'Business - Phone Net Adds', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[Business - Phone Gross Adds] - [Business - Phone Disconnects]', TRUE),
    (83, 'Challenger Model', 'Consumer - Average Phone Connections', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ROLLING_AVG([Consumer - Phone Connections], 2)', TRUE),
    (84, 'Challenger Model', 'Business - Average Phone Connections', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ROLLING_AVG([Business - Phone Connections], 2)', TRUE),
    (85, 'Challenger Model', 'Consumer - Phone Connections', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ROLL_FORWARD(connections=[Consumer - Phone Connections], net_adds=[Consumer - Phone Net Adds], adj=[Calculated Consumer - Phone Connections Adj])', TRUE),
    (86, 'Challenger Model', 'Business - Phone Connections', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ROLL_FORWARD(connections=[Business - Phone Connections], net_adds=[Business - Phone Net Adds], adj=[Calculated Business - Phone Connections Adj])', TRUE),
    (87, 'Challenger Model', 'Consumer - Phone Churn %', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SAFE_DIVIDE([Consumer - Phone Disconnects], [Consumer - Average Phone Connections])', TRUE),
    (88, 'Challenger Model', 'Business - Phone Churn %', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SAFE_DIVIDE([Business - Phone Disconnects], [Business - Average Phone Connections])', TRUE),
    (89, 'Challenger Model', 'Consumer - Postpaid Net Adds', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[Consumer - PostPaid Gross Adds] - [Consumer - PostPaid Disconnects]', TRUE),
    (90, 'Challenger Model', 'Business - Postpaid Net Adds', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[Business - PostPaid Gross Adds] - [Business - PostPaid Disconnects]', TRUE),
    (91, 'Challenger Model', 'Consumer - Wireless Net Accounts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[Consumer - Wireless Gross New Accounts] - [Consumer - Wireless Lost Accounts] + [Consumer - Wireless Account Splits] - [Consumer - Wireless Account Merges]', TRUE),
    (92, 'Challenger Model', 'Business - Wireless Net Accounts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[Business - Wireless Gross New Accounts] - [Business - Wireless Lost Accounts] + [Business - Wireless Account Splits] - [Business - Wireless Account Merges]', TRUE)
  ])
),
Config AS (
  SELECT
    Config_ID,
    TRIM(LineItem) AS LineItem,
    IF((ProfitCentre IS NULL OR TRIM(ProfitCentre) = '' OR UPPER(TRIM(ProfitCentre)) IN ('ALL', 'NA')), 'ALL', TRIM(ProfitCentre)) AS ProfitCentre,
    NULLIF(TRIM(ProfitCentreHierarchyName), '') AS ProfitCentreHierarchyName,
    IF((Account IS NULL OR TRIM(Account) = '' OR UPPER(TRIM(Account)) IN ('ALL', 'NA')), 'ALL', TRIM(Account)) AS Account,
    NULLIF(TRIM(AccountHierarchy), '') AS AccountHierarchy,
    IF((CompanyCode IS NULL OR TRIM(CompanyCode) = '' OR UPPER(TRIM(CompanyCode)) IN ('ALL', 'NA')), 'ALL', TRIM(CompanyCode)) AS CompanyCode,
    IF((ServiceType IS NULL OR TRIM(ServiceType) = '' OR UPPER(TRIM(ServiceType)) IN ('ALL', 'NA')), 'ALL', TRIM(ServiceType)) AS ServiceType,
    NULLIF(TRIM(ServiceTypeHierarchy), '') AS ServiceTypeHierarchy,
    IF((Market IS NULL OR TRIM(Market) = '' OR UPPER(TRIM(Market)) IN ('ALL', 'NA')), 'ALL', TRIM(Market)) AS Market,
    IF((Product IS NULL OR TRIM(Product) = '' OR UPPER(TRIM(Product)) IN ('ALL', 'NA')), 'ALL', TRIM(Product)) AS Product,
    NULLIF(TRIM(ProductHierarchy), '') AS ProductHierarchy,
    IF((Equipment IS NULL OR TRIM(Equipment) = '' OR UPPER(TRIM(Equipment)) IN ('ALL', 'NA')), 'ALL', TRIM(Equipment)) AS Equipment,
    NULLIF(TRIM(EquipmentHierachy), '') AS EquipmentHierachy,
    IF((DistributionChannel IS NULL OR TRIM(DistributionChannel) = '' OR UPPER(TRIM(DistributionChannel)) IN ('ALL', 'NA')), 'ALL', TRIM(DistributionChannel)) AS DistributionChannel,
    NULLIF(TRIM(DistributionChannelHierarchy), '') AS DistributionChannelHierarchy
  FROM config_csv
  WHERE (Formula IS NULL OR TRIM(Formula) = '')
),
profitcentre_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.ProfitCentre) AS ProfitCentreGranular
  FROM Config C
  LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.ProfitCentre = H.parent
    AND H.dimension_name = 'Profit_Center'
    AND (CASE WHEN C.ProfitCentreHierarchyName IS NULL THEN H.is_primary = TRUE ELSE H.hierarchy_name = C.ProfitCentreHierarchyName END)
  WHERE C.ProfitCentre <> 'ALL'
),
account_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.Account) AS AccountGranular
  FROM Config C
  LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.Account = H.parent
    AND H.dimension_name = 'Account'
    AND (CASE WHEN C.AccountHierarchy IS NULL THEN H.is_primary = TRUE ELSE H.hierarchy_name = C.AccountHierarchy END)
  WHERE C.Account <> 'ALL'
),
companycode_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.CompanyCode) AS CompanyCodeGranular
  FROM Config C
  LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.CompanyCode = H.parent
    AND H.dimension_name = 'Company_Code'
    AND (H.is_primary = TRUE)
  WHERE C.CompanyCode <> 'ALL'
),
servicetype_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.ServiceType) AS ServiceTypeGranular
  FROM Config C
  LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.ServiceType = H.parent
    AND H.dimension_name = 'Service_Type'
    AND (CASE WHEN C.ServiceTypeHierarchy IS NULL THEN H.is_primary = TRUE ELSE H.hierarchy_name = C.ServiceTypeHierarchy END)
  WHERE C.ServiceType <> 'ALL'
),
market_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.Market) AS MarketGranular
  FROM Config C
  LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.Market = H.parent
    AND H.dimension_name = 'Market'
    AND (H.is_primary = TRUE)
  WHERE C.Market <> 'ALL'
),
product_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.Product) AS ProductGranular
  FROM Config C
  LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.Product = H.parent
    AND H.dimension_name = 'Product'
    AND (CASE WHEN C.ProductHierarchy IS NULL THEN H.is_primary = TRUE ELSE H.hierarchy_name = C.ProductHierarchy END)
  WHERE C.Product <> 'ALL'
),
equipment_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.Equipment) AS EquipmentGranular
  FROM Config C
  LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.Equipment = H.parent
    AND H.dimension_name = 'Equipment'
    AND (CASE WHEN C.EquipmentHierachy IS NULL THEN H.is_primary = TRUE ELSE H.hierarchy_name = C.EquipmentHierachy END)
  WHERE C.Equipment <> 'ALL'
),
distributionchannel_mapping AS (
  SELECT DISTINCT C.Config_ID, COALESCE(H.node, C.DistributionChannel) AS DistributionChannelGranular
  FROM Config C
  LEFT JOIN `vz-it-np-j0nv-dev-oddo-0.od_enriched_edmcs.edm_master_incl_alt_hierarchies_v` H
    ON C.DistributionChannel = H.parent
    AND H.dimension_name = 'Distribution_Channel'
    AND (CASE WHEN C.DistributionChannelHierarchy IS NULL THEN H.is_primary = TRUE ELSE H.hierarchy_name = C.DistributionChannelHierarchy END)
  WHERE C.DistributionChannel <> 'ALL'
),
actuals AS (
  SELECT T.year, T.period, T.profit_center, T.Account, T.Company_Code, T.Service_Type, T.Market, T.Product, T.Equipment, T.Distribution_Channel, SUM(T.amount) AS amount
  FROM `vz-it-np-j0nv-dev-oddo-0.od_published_epm.epm_p00all_actuals_fullhist_v` T
  INNER JOIN (SELECT DISTINCT ProfitCentreGranular FROM profitcentre_mapping) F_ProfitCentre
    ON F_ProfitCentre.ProfitCentreGranular = T.profit_center
  INNER JOIN (SELECT DISTINCT AccountGranular FROM account_mapping) F_Account
    ON F_Account.AccountGranular = T.Account
  INNER JOIN (SELECT DISTINCT MarketGranular FROM market_mapping) F_Market
    ON F_Market.MarketGranular = T.Market
  INNER JOIN (SELECT DISTINCT ProductGranular FROM product_mapping) F_Product
    ON F_Product.ProductGranular = T.Product
  INNER JOIN (SELECT DISTINCT DistributionChannelGranular FROM distributionchannel_mapping) F_DistributionChannel
    ON F_DistributionChannel.DistributionChannelGranular = T.Distribution_Channel
  WHERE T.year IN (
      SELECT FORMAT_DATE('FY%y', DATE_SUB(DATE_ADD(CURRENT_DATE(), INTERVAL 0 MONTH), INTERVAL i YEAR))
      FROM UNNEST(GENERATE_ARRAY(0, 4)) AS i)
  GROUP BY T.year, T.period, T.profit_center, T.Account, T.Company_Code, T.Service_Type, T.Market, T.Product, T.Equipment, T.Distribution_Channel
),
base_values AS (
  SELECT C.LineItem, A.year AS year, A.period AS month, SUM(A.amount) AS Amount
  FROM actuals A
  INNER JOIN profitcentre_mapping M_ProfitCentre
    ON M_ProfitCentre.ProfitCentreGranular = A.profit_center
  INNER JOIN Config C
    ON C.Config_ID = M_ProfitCentre.Config_ID
  INNER JOIN account_mapping M_Account
    ON M_Account.Config_ID = C.Config_ID
    AND M_Account.AccountGranular = A.Account
  INNER JOIN market_mapping M_Market
    ON M_Market.Config_ID = C.Config_ID
    AND M_Market.MarketGranular = A.Market
  INNER JOIN product_mapping M_Product
    ON M_Product.Config_ID = C.Config_ID
    AND M_Product.ProductGranular = A.Product
  INNER JOIN distributionchannel_mapping M_DistributionChannel
    ON M_DistributionChannel.Config_ID = C.Config_ID
    AND M_DistributionChannel.DistributionChannelGranular = A.Distribution_Channel
  LEFT JOIN companycode_mapping M_CompanyCode
    ON M_CompanyCode.Config_ID = C.Config_ID
    AND M_CompanyCode.CompanyCodeGranular = A.Company_Code
  LEFT JOIN servicetype_mapping M_ServiceType
    ON M_ServiceType.Config_ID = C.Config_ID
    AND M_ServiceType.ServiceTypeGranular = A.Service_Type
  LEFT JOIN equipment_mapping M_Equipment
    ON M_Equipment.Config_ID = C.Config_ID
    AND M_Equipment.EquipmentGranular = A.Equipment
  WHERE
    (C.CompanyCode = 'ALL' OR M_CompanyCode.Config_ID IS NOT NULL)
    AND (C.ServiceType = 'ALL' OR M_ServiceType.Config_ID IS NOT NULL)
    AND (C.Equipment = 'ALL' OR M_Equipment.Config_ID IS NOT NULL)
  GROUP BY C.LineItem, A.year, A.period
)
SELECT LineItem, year, month, Amount
FROM base_values;

WITH
monthly_summary AS (
  SELECT year, month, LineItem, CAST(COALESCE(SUM(Amount), 0) AS FLOAT64) AS Amount
  FROM `base_values`
  GROUP BY year, month, LineItem
),

monthly_summary_dated AS (
  -- month_date orders the months for LAG / rolling / roll-forward; a year or month it cannot read stops the query
  SELECT
    year, month, LineItem, Amount,
    IF(month_date IS NULL,
       ERROR(FORMAT('cannot turn year %T / month %T into a date (fix the month mapping or add the period to EXCLUDED_PERIODS)', year, month)),
       month_date) AS month_date
  FROM (
    SELECT *, SAFE.DATE(IF(year_num < 100, 2000 + year_num, year_num), month_num, 1) AS month_date
    FROM (
      SELECT
        *,
        SAFE_CAST(REGEXP_REPLACE(CAST(year AS STRING), r'^[Ff][Yy]', '') AS INT64) AS year_num,
        CASE LOWER(TRIM(CAST(month AS STRING)))
          WHEN 'jan' THEN 1 WHEN 'january' THEN 1
          WHEN 'feb' THEN 2 WHEN 'february' THEN 2
          WHEN 'mar' THEN 3 WHEN 'march' THEN 3
          WHEN 'apr' THEN 4 WHEN 'april' THEN 4
          WHEN 'may' THEN 5
          WHEN 'jun' THEN 6 WHEN 'june' THEN 6
          WHEN 'jul' THEN 7 WHEN 'july' THEN 7
          WHEN 'aug' THEN 8 WHEN 'august' THEN 8
          WHEN 'sep' THEN 9 WHEN 'september' THEN 9
          WHEN 'oct' THEN 10 WHEN 'october' THEN 10
          WHEN 'nov' THEN 11 WHEN 'november' THEN 11
          WHEN 'dec' THEN 12 WHEN 'december' THEN 12
          ELSE SAFE_CAST(TRIM(CAST(month AS STRING)) AS INT64)
        END AS month_num
      FROM monthly_summary
    )
  )
),

combined_0 AS (
  SELECT year, month, month_date, LineItem, Amount FROM monthly_summary_dated
),

last_actual_month AS (
  -- roll forwards, and the line items calculated from them, run through this month: the latest month in which a line
  -- item behind a net_adds= has a value (later months only hold open-period plugs, e.g. Adj)
  SELECT MAX(month_date) AS max_month_date
  FROM monthly_summary_dated
  WHERE Amount <> 0 AND LineItem IN (
    'Consumer - Phone Gross Adds',
    'Business - Phone Gross Adds',
    'Consumer - Phone Disconnects',
    'Business - Phone Disconnects',
    'Consumer - FWA Gross Adds',
    'Business - FWA Gross Adds',
    'Consumer - FWA Disconnects',
    'Business - FWA Disconnects',
    'Consumer - Fios Fiber Gross Adds',
    'Consumer - Frontier Fiber Gross Adds',
    'Business - Fios Fiber Gross Adds',
    'Business - Frontier Fiber Gross Adds',
    'Consumer - Fios Fiber Disconnects',
    'Consumer - Frontier Fiber Disconnects',
    'Business - Fios Fiber Disconnects',
    'Business - Frontier Fiber Disconnects'
  )
),

tier_1_calc AS (
  -- one row per month; [X] = SUM(IF(LineItem = 'X', Amount, 0))
  SELECT
    year, month, month_date,
    -- Calculated Consumer - Prepaid Phone Safelink Net Adds = [Calculated Consumer - Prepaid Phone SafeLink Gross Adds] - [Calculated Consumer - Prepaid Phone SafeLink Disconnects]  (Config_ID 51)
    SUM(IF(LineItem = 'Calculated Consumer - Prepaid Phone SafeLink Gross Adds', Amount, 0)) - SUM(IF(LineItem = 'Calculated Consumer - Prepaid Phone SafeLink Disconnects', Amount, 0)) AS f_51,
    -- Calculated Consumer - Prepaid Phone Equip Net Adds = [Calculated Consumer - Prepaid Phone Equip. Gross Adds] - [Calculated Consumer - Prepaid Phone Equip. Disconnects]  (Config_ID 52)
    SUM(IF(LineItem = 'Calculated Consumer - Prepaid Phone Equip. Gross Adds', Amount, 0)) - SUM(IF(LineItem = 'Calculated Consumer - Prepaid Phone Equip. Disconnects', Amount, 0)) AS f_52,
    -- Calculated Consumer - Prepaid Safelink Net Adds = [Calculated Consumer - Prepaid SafeLink Gross Adds] - [Calculated Consumer - Prepaid SafeLink Disconnects]  (Config_ID 54)
    SUM(IF(LineItem = 'Calculated Consumer - Prepaid SafeLink Gross Adds', Amount, 0)) - SUM(IF(LineItem = 'Calculated Consumer - Prepaid SafeLink Disconnects', Amount, 0)) AS f_54,
    -- Calculated Consumer - Prepaid Equip Net Adds = [Calculated Consumer - Prepaid Equip. Gross Adds] - [Calculated Consumer - Prepaid Equip. Disconnects]  (Config_ID 55)
    SUM(IF(LineItem = 'Calculated Consumer - Prepaid Equip. Gross Adds', Amount, 0)) - SUM(IF(LineItem = 'Calculated Consumer - Prepaid Equip. Disconnects', Amount, 0)) AS f_55,
    -- Consumer - FWA Net Adds = [Consumer - FWA Gross Adds] - [Consumer - FWA Disconnects]  (Config_ID 57)
    SUM(IF(LineItem = 'Consumer - FWA Gross Adds', Amount, 0)) - SUM(IF(LineItem = 'Consumer - FWA Disconnects', Amount, 0)) AS f_57,
    -- Business - FWA Net Adds = [Business - FWA Gross Adds] - [Business - FWA Disconnects]  (Config_ID 58)
    SUM(IF(LineItem = 'Business - FWA Gross Adds', Amount, 0)) - SUM(IF(LineItem = 'Business - FWA Disconnects', Amount, 0)) AS f_58,
    -- Consumer - Fios Fiber Net Adds = [Consumer - Fios Fiber Gross Adds] - [Consumer - Fios Fiber Disconnects]  (Config_ID 77)
    SUM(IF(LineItem = 'Consumer - Fios Fiber Gross Adds', Amount, 0)) - SUM(IF(LineItem = 'Consumer - Fios Fiber Disconnects', Amount, 0)) AS f_77,
    -- Consumer - Frontier Fiber Net Adds = [Consumer - Frontier Fiber Gross Adds] - [Consumer - Frontier Fiber Disconnects]  (Config_ID 78)
    SUM(IF(LineItem = 'Consumer - Frontier Fiber Gross Adds', Amount, 0)) - SUM(IF(LineItem = 'Consumer - Frontier Fiber Disconnects', Amount, 0)) AS f_78,
    -- Business - Fios Fiber Net Adds = [Business - Fios Fiber Gross Adds] - [Business - Fios Fiber Disconnects]  (Config_ID 79)
    SUM(IF(LineItem = 'Business - Fios Fiber Gross Adds', Amount, 0)) - SUM(IF(LineItem = 'Business - Fios Fiber Disconnects', Amount, 0)) AS f_79,
    -- Business - Frontier Fiber Net Adds = [Business - Frontier Fiber Gross Adds] - [Business - Frontier Fiber Disconnects]  (Config_ID 80)
    SUM(IF(LineItem = 'Business - Frontier Fiber Gross Adds', Amount, 0)) - SUM(IF(LineItem = 'Business - Frontier Fiber Disconnects', Amount, 0)) AS f_80,
    -- Consumer - Phone Net Adds = [Consumer - Phone Gross Adds] - [Consumer - Phone Disconnects]  (Config_ID 81)
    SUM(IF(LineItem = 'Consumer - Phone Gross Adds', Amount, 0)) - SUM(IF(LineItem = 'Consumer - Phone Disconnects', Amount, 0)) AS f_81,
    -- Business - Phone Net Adds = [Business - Phone Gross Adds] - [Business - Phone Disconnects]  (Config_ID 82)
    SUM(IF(LineItem = 'Business - Phone Gross Adds', Amount, 0)) - SUM(IF(LineItem = 'Business - Phone Disconnects', Amount, 0)) AS f_82,
    -- Consumer - Postpaid Net Adds = [Consumer - PostPaid Gross Adds] - [Consumer - PostPaid Disconnects]  (Config_ID 89)
    SUM(IF(LineItem = 'Consumer - PostPaid Gross Adds', Amount, 0)) - SUM(IF(LineItem = 'Consumer - PostPaid Disconnects', Amount, 0)) AS f_89,
    -- Business - Postpaid Net Adds = [Business - PostPaid Gross Adds] - [Business - PostPaid Disconnects]  (Config_ID 90)
    SUM(IF(LineItem = 'Business - PostPaid Gross Adds', Amount, 0)) - SUM(IF(LineItem = 'Business - PostPaid Disconnects', Amount, 0)) AS f_90,
    -- Consumer - Wireless Net Accounts = [Consumer - Wireless Gross New Accounts] - [Consumer - Wireless Lost Accounts] + [Consumer - Wireless Account Splits] - [Consumer - Wireless Account Merges]  (Config_ID 91)
    SUM(IF(LineItem = 'Consumer - Wireless Gross New Accounts', Amount, 0)) - SUM(IF(LineItem = 'Consumer - Wireless Lost Accounts', Amount, 0)) + SUM(IF(LineItem = 'Consumer - Wireless Account Splits', Amount, 0)) - SUM(IF(LineItem = 'Consumer - Wireless Account Merges', Amount, 0)) AS f_91,
    -- Business - Wireless Net Accounts = [Business - Wireless Gross New Accounts] - [Business - Wireless Lost Accounts] + [Business - Wireless Account Splits] - [Business - Wireless Account Merges]  (Config_ID 92)
    SUM(IF(LineItem = 'Business - Wireless Gross New Accounts', Amount, 0)) - SUM(IF(LineItem = 'Business - Wireless Lost Accounts', Amount, 0)) + SUM(IF(LineItem = 'Business - Wireless Account Splits', Amount, 0)) - SUM(IF(LineItem = 'Business - Wireless Account Merges', Amount, 0)) AS f_92
  FROM combined_0
  GROUP BY year, month, month_date
),

tier_1 AS (
  SELECT calc.year, calc.month, calc.month_date, item.LineItem, COALESCE(item.Amount, 0) AS Amount
  FROM tier_1_calc AS calc
  CROSS JOIN UNNEST(ARRAY<STRUCT<LineItem STRING, Amount FLOAT64>>[
    ('Calculated Consumer - Prepaid Phone Safelink Net Adds', calc.f_51),
    ('Calculated Consumer - Prepaid Phone Equip Net Adds', calc.f_52),
    ('Calculated Consumer - Prepaid Safelink Net Adds', calc.f_54),
    ('Calculated Consumer - Prepaid Equip Net Adds', calc.f_55),
    ('Consumer - FWA Net Adds', calc.f_57),
    ('Business - FWA Net Adds', calc.f_58),
    ('Consumer - Fios Fiber Net Adds', calc.f_77),
    ('Consumer - Frontier Fiber Net Adds', calc.f_78),
    ('Business - Fios Fiber Net Adds', calc.f_79),
    ('Business - Frontier Fiber Net Adds', calc.f_80),
    ('Consumer - Phone Net Adds', calc.f_81),
    ('Business - Phone Net Adds', calc.f_82),
    ('Consumer - Postpaid Net Adds', calc.f_89),
    ('Business - Postpaid Net Adds', calc.f_90),
    ('Consumer - Wireless Net Accounts', calc.f_91),
    ('Business - Wireless Net Accounts', calc.f_92)
  ]) AS item
),

tier_1_names AS (
  SELECT LineItem FROM UNNEST(ARRAY<STRING>[
    'Calculated Consumer - Prepaid Phone Safelink Net Adds',
    'Calculated Consumer - Prepaid Phone Equip Net Adds',
    'Calculated Consumer - Prepaid Safelink Net Adds',
    'Calculated Consumer - Prepaid Equip Net Adds',
    'Consumer - FWA Net Adds',
    'Business - FWA Net Adds',
    'Consumer - Fios Fiber Net Adds',
    'Consumer - Frontier Fiber Net Adds',
    'Business - Fios Fiber Net Adds',
    'Business - Frontier Fiber Net Adds',
    'Consumer - Phone Net Adds',
    'Business - Phone Net Adds',
    'Consumer - Postpaid Net Adds',
    'Business - Postpaid Net Adds',
    'Consumer - Wireless Net Accounts',
    'Business - Wireless Net Accounts'
  ]) AS LineItem
),

combined_1 AS (
  -- anti-join: a calculated line item replaces source rows with the same name (no double counting)
  SELECT c.year, c.month, c.month_date, c.LineItem, c.Amount
  FROM combined_0 AS c
  LEFT JOIN tier_1_names AS n
    ON c.LineItem = n.LineItem
  WHERE n.LineItem IS NULL
  UNION ALL
  SELECT year, month, month_date, LineItem, Amount FROM tier_1
),

tier_2_calc AS (
  -- one row per month; [X] = SUM(IF(LineItem = 'X', Amount, 0))
  SELECT
    year, month, month_date,
    -- Consumer - Prepaid Phone Net Adds excl. Safelink = [Calculated Consumer - Prepaid Phone Equip Net Adds] - [Calculated Consumer - Prepaid Phone Safelink Net Adds]  (Config_ID 53)
    SUM(IF(LineItem = 'Calculated Consumer - Prepaid Phone Equip Net Adds', Amount, 0)) - SUM(IF(LineItem = 'Calculated Consumer - Prepaid Phone Safelink Net Adds', Amount, 0)) AS f_53,
    -- Consumer - Prepaid Net Adds excl. Safelink = [Calculated Consumer - Prepaid Equip Net Adds] - [Calculated Consumer - Prepaid Safelink Net Adds]  (Config_ID 56)
    SUM(IF(LineItem = 'Calculated Consumer - Prepaid Equip Net Adds', Amount, 0)) - SUM(IF(LineItem = 'Calculated Consumer - Prepaid Safelink Net Adds', Amount, 0)) AS f_56
  FROM combined_1
  GROUP BY year, month, month_date
),

tier_2_rf_segments AS (
  SELECT *
  FROM UNNEST(ARRAY<STRUCT<line_item STRING, net_adds_item STRING, adj_item STRING, actual_item STRING,
                           beginning_item STRING>>[
    -- Consumer - FWA Connections = ROLL_FORWARD(connections=[Consumer - FWA Connections], net_adds=[Consumer - FWA Net Adds], adj=[Calculated Consumer - FWA Connections Adj])  (Config_ID 61)
    ('Consumer - FWA Connections', 'Consumer - FWA Net Adds', 'Calculated Consumer - FWA Connections Adj', NULL, NULL),
    -- Business - FWA Connections = ROLL_FORWARD(connections=[Business - FWA Connections], net_adds=[Business - FWA Net Adds], adj=[Calculated Business - FWA Connections Adj])  (Config_ID 62)
    ('Business - FWA Connections', 'Business - FWA Net Adds', 'Calculated Business - FWA Connections Adj', NULL, NULL),
    -- Consumer - Fios Fiber Connections = ROLL_FORWARD(connections=[Consumer - Fios Fiber Connections], net_adds=[Consumer - Fios Fiber Net Adds], adj=[Calculated Consumer - Fios Fiber Connections Adj])  (Config_ID 69)
    ('Consumer - Fios Fiber Connections', 'Consumer - Fios Fiber Net Adds', 'Calculated Consumer - Fios Fiber Connections Adj', NULL, NULL),
    -- Consumer - Frontier Fiber Connections = ROLL_FORWARD(connections=[Consumer - Frontier Fiber Connections], net_adds=[Consumer - Frontier Fiber Net Adds], adj=[Calculated Consumer - Frontier Fiber Connections Adj])  (Config_ID 70)
    ('Consumer - Frontier Fiber Connections', 'Consumer - Frontier Fiber Net Adds', 'Calculated Consumer - Frontier Fiber Connections Adj', NULL, NULL),
    -- Business - Fios Fiber Connections = ROLL_FORWARD(connections=[Business - Fios Fiber Connections], net_adds=[Business - Fios Fiber Net Adds], adj=[Calculated Business - Fios Fiber Connections Adj])  (Config_ID 71)
    ('Business - Fios Fiber Connections', 'Business - Fios Fiber Net Adds', 'Calculated Business - Fios Fiber Connections Adj', NULL, NULL),
    -- Business - Frontier Fiber Connections = ROLL_FORWARD(connections=[Business - Frontier Fiber Connections], net_adds=[Business - Frontier Fiber Net Adds], adj=[Calculated Business - Frontier Fiber Connections Adj])  (Config_ID 72)
    ('Business - Frontier Fiber Connections', 'Business - Frontier Fiber Net Adds', 'Calculated Business - Frontier Fiber Connections Adj', NULL, NULL),
    -- Consumer - Phone Connections = ROLL_FORWARD(connections=[Consumer - Phone Connections], net_adds=[Consumer - Phone Net Adds], adj=[Calculated Consumer - Phone Connections Adj])  (Config_ID 85)
    ('Consumer - Phone Connections', 'Consumer - Phone Net Adds', 'Calculated Consumer - Phone Connections Adj', NULL, 'Consumer - Phone Connections Beginning'),
    -- Business - Phone Connections = ROLL_FORWARD(connections=[Business - Phone Connections], net_adds=[Business - Phone Net Adds], adj=[Calculated Business - Phone Connections Adj])  (Config_ID 86)
    ('Business - Phone Connections', 'Business - Phone Net Adds', 'Calculated Business - Phone Connections Adj', NULL, 'Business - Phone Connections Beginning')
  ])
),

tier_2_rf_inputs AS (
  -- one row per roll-forward per month: the actual and the beginning balance (NULL = none) and the month's movement
  SELECT
    s.line_item AS LineItem, c.year, c.month, c.month_date,
    NULLIF(SUM(IF(c.LineItem = s.actual_item, c.Amount, NULL)), 0) AS actual_value,
    NULLIF(SUM(IF(c.LineItem = s.beginning_item, c.Amount, NULL)), 0) AS beginning_value,
    SUM(IF(c.LineItem IN (s.net_adds_item, s.adj_item), c.Amount, 0)) AS movement
  FROM combined_1 AS c
  CROSS JOIN tier_2_rf_segments AS s
  GROUP BY s.line_item, c.year, c.month, c.month_date
),

tier_2_rf_running AS (
  SELECT
    *,
    -- the month's closing balance, where it is known: the actual, else the next month's beginning balance (December
    -- shows January's), else the month's own beginning balance + its movement (the first month of the data)
    COALESCE(
      actual_value,
      IF(LEAD(month_date) OVER w = DATE_ADD(month_date, INTERVAL 1 MONTH), LEAD(beginning_value) OVER w, NULL),
      beginning_value + movement
    ) AS known_value,
    SUM(movement) OVER (
      PARTITION BY LineItem ORDER BY month_date
      ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
    ) AS cum_movement
  FROM tier_2_rf_inputs
  WINDOW w AS (PARTITION BY LineItem ORDER BY month_date)
),

tier_2_rf AS (
  SELECT
    LineItem, year, month, month_date,
    COALESCE(
      -- a known closing balance wins in its own month
      known_value,
      -- latest earlier known balance + movement accumulated since that month
      LAST_VALUE(known_value IGNORE NULLS) OVER w_prior
        + cum_movement
        - LAST_VALUE(IF(known_value IS NOT NULL, cum_movement, NULL) IGNORE NULLS) OVER w_prior,
      -- nothing known yet: roll forward from an opening balance of 0
      cum_movement
    ) AS Amount
  FROM tier_2_rf_running
  WINDOW w_prior AS (
    PARTITION BY LineItem ORDER BY month_date
    ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
  )
),

tier_2 AS (
  SELECT calc.year, calc.month, calc.month_date, item.LineItem, COALESCE(item.Amount, 0) AS Amount
  FROM tier_2_calc AS calc
  CROSS JOIN UNNEST(ARRAY<STRUCT<LineItem STRING, Amount FLOAT64>>[
    ('Consumer - Prepaid Phone Net Adds excl. Safelink', calc.f_53),
    ('Consumer - Prepaid Net Adds excl. Safelink', calc.f_56)
  ]) AS item
  UNION ALL
  SELECT year, month, month_date, LineItem, COALESCE(Amount, 0) AS Amount
  FROM tier_2_rf
  CROSS JOIN last_actual_month AS l
  WHERE month_date <= l.max_month_date
),

tier_2_names AS (
  SELECT LineItem FROM UNNEST(ARRAY<STRING>[
    'Consumer - Prepaid Phone Net Adds excl. Safelink',
    'Consumer - Prepaid Net Adds excl. Safelink',
    'Consumer - FWA Connections',
    'Business - FWA Connections',
    'Consumer - Fios Fiber Connections',
    'Consumer - Frontier Fiber Connections',
    'Business - Fios Fiber Connections',
    'Business - Frontier Fiber Connections',
    'Consumer - Phone Connections',
    'Business - Phone Connections'
  ]) AS LineItem
),

combined_2 AS (
  -- anti-join: a calculated line item replaces source rows with the same name (no double counting)
  SELECT c.year, c.month, c.month_date, c.LineItem, c.Amount
  FROM combined_1 AS c
  LEFT JOIN tier_2_names AS n
    ON c.LineItem = n.LineItem
  WHERE n.LineItem IS NULL
  UNION ALL
  SELECT year, month, month_date, LineItem, Amount FROM tier_2
),

tier_3_calc AS (
  -- one row per month; [X] = SUM(IF(LineItem = 'X', Amount, 0))
  SELECT
    year, month, month_date,
    -- Consumer - FWA Average Connections = ROLLING_AVG([Consumer - FWA Connections], 2)  (Config_ID 59)
    AVG(SUM(IF(LineItem = 'Consumer - FWA Connections', Amount, 0))) OVER (ORDER BY month_date ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS f_59,
    -- Business - FWA Average Connections = ROLLING_AVG([Business - FWA Connections], 2)  (Config_ID 60)
    AVG(SUM(IF(LineItem = 'Business - FWA Connections', Amount, 0))) OVER (ORDER BY month_date ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS f_60,
    -- Consumer - Fios Average Fiber Connections = ROLLING_AVG([Consumer - Fios Fiber Connections], 2)  (Config_ID 65)
    AVG(SUM(IF(LineItem = 'Consumer - Fios Fiber Connections', Amount, 0))) OVER (ORDER BY month_date ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS f_65,
    -- Consumer - Frontier Average Fiber Connections = ROLLING_AVG([Consumer - Frontier Fiber Connections], 2)  (Config_ID 66)
    AVG(SUM(IF(LineItem = 'Consumer - Frontier Fiber Connections', Amount, 0))) OVER (ORDER BY month_date ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS f_66,
    -- Business - Fios Average Fiber Connections = ROLLING_AVG([Business - Fios Fiber Connections], 2)  (Config_ID 67)
    AVG(SUM(IF(LineItem = 'Business - Fios Fiber Connections', Amount, 0))) OVER (ORDER BY month_date ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS f_67,
    -- Business - Frontier Average Fiber Connections = ROLLING_AVG([Business - Frontier Fiber Connections], 2)  (Config_ID 68)
    AVG(SUM(IF(LineItem = 'Business - Frontier Fiber Connections', Amount, 0))) OVER (ORDER BY month_date ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS f_68,
    -- Consumer - Average Phone Connections = ROLLING_AVG([Consumer - Phone Connections], 2)  (Config_ID 83)
    AVG(SUM(IF(LineItem = 'Consumer - Phone Connections', Amount, 0))) OVER (ORDER BY month_date ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS f_83,
    -- Business - Average Phone Connections = ROLLING_AVG([Business - Phone Connections], 2)  (Config_ID 84)
    AVG(SUM(IF(LineItem = 'Business - Phone Connections', Amount, 0))) OVER (ORDER BY month_date ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS f_84
  FROM combined_2
  GROUP BY year, month, month_date
),

tier_3 AS (
  SELECT calc.year, calc.month, calc.month_date, item.LineItem, COALESCE(item.Amount, 0) AS Amount
  FROM tier_3_calc AS calc
  CROSS JOIN last_actual_month AS l
  CROSS JOIN UNNEST(ARRAY<STRUCT<LineItem STRING, Amount FLOAT64, to_last_actual BOOL>>[
    ('Consumer - FWA Average Connections', calc.f_59, TRUE),
    ('Business - FWA Average Connections', calc.f_60, TRUE),
    ('Consumer - Fios Average Fiber Connections', calc.f_65, TRUE),
    ('Consumer - Frontier Average Fiber Connections', calc.f_66, TRUE),
    ('Business - Fios Average Fiber Connections', calc.f_67, TRUE),
    ('Business - Frontier Average Fiber Connections', calc.f_68, TRUE),
    ('Consumer - Average Phone Connections', calc.f_83, TRUE),
    ('Business - Average Phone Connections', calc.f_84, TRUE)
  ]) AS item
  -- a line item calculated from a roll forward stops where the roll forward does
  WHERE NOT item.to_last_actual OR calc.month_date <= l.max_month_date
),

tier_3_names AS (
  SELECT LineItem FROM UNNEST(ARRAY<STRING>[
    'Consumer - FWA Average Connections',
    'Business - FWA Average Connections',
    'Consumer - Fios Average Fiber Connections',
    'Consumer - Frontier Average Fiber Connections',
    'Business - Fios Average Fiber Connections',
    'Business - Frontier Average Fiber Connections',
    'Consumer - Average Phone Connections',
    'Business - Average Phone Connections'
  ]) AS LineItem
),

combined_3 AS (
  -- anti-join: a calculated line item replaces source rows with the same name (no double counting)
  SELECT c.year, c.month, c.month_date, c.LineItem, c.Amount
  FROM combined_2 AS c
  LEFT JOIN tier_3_names AS n
    ON c.LineItem = n.LineItem
  WHERE n.LineItem IS NULL
  UNION ALL
  SELECT year, month, month_date, LineItem, Amount FROM tier_3
),

tier_4_calc AS (
  -- one row per month; [X] = SUM(IF(LineItem = 'X', Amount, 0))
  SELECT
    year, month, month_date,
    -- Consumer - FWA Churn % = SAFE_DIVIDE([Consumer - FWA Disconnects], [Consumer - FWA Average Connections])  (Config_ID 63)
    SAFE_DIVIDE(SUM(IF(LineItem = 'Consumer - FWA Disconnects', Amount, 0)), SUM(IF(LineItem = 'Consumer - FWA Average Connections', Amount, 0))) AS f_63,
    -- Business - FWA Churn % = SAFE_DIVIDE([Business - FWA Disconnects], [Business - FWA Average Connections])  (Config_ID 64)
    SAFE_DIVIDE(SUM(IF(LineItem = 'Business - FWA Disconnects', Amount, 0)), SUM(IF(LineItem = 'Business - FWA Average Connections', Amount, 0))) AS f_64,
    -- Consumer - Fios Fiber Churn % = SAFE_DIVIDE([Consumer - Fios Fiber Disconnects], [Consumer - Fios Average Fiber Connections])  (Config_ID 73)
    SAFE_DIVIDE(SUM(IF(LineItem = 'Consumer - Fios Fiber Disconnects', Amount, 0)), SUM(IF(LineItem = 'Consumer - Fios Average Fiber Connections', Amount, 0))) AS f_73,
    -- Consumer - Frontier Fiber Churn % = SAFE_DIVIDE([Consumer - Frontier Fiber Disconnects], [Consumer - Frontier Average Fiber Connections])  (Config_ID 74)
    SAFE_DIVIDE(SUM(IF(LineItem = 'Consumer - Frontier Fiber Disconnects', Amount, 0)), SUM(IF(LineItem = 'Consumer - Frontier Average Fiber Connections', Amount, 0))) AS f_74,
    -- Business - Fios Fiber Churn % = SAFE_DIVIDE([Business - Fios Fiber Disconnects], [Business - Fios Average Fiber Connections])  (Config_ID 75)
    SAFE_DIVIDE(SUM(IF(LineItem = 'Business - Fios Fiber Disconnects', Amount, 0)), SUM(IF(LineItem = 'Business - Fios Average Fiber Connections', Amount, 0))) AS f_75,
    -- Business - Frontier Fiber Churn % = SAFE_DIVIDE([Business - Frontier Fiber Disconnects], [Business - Frontier Average Fiber Connections])  (Config_ID 76)
    SAFE_DIVIDE(SUM(IF(LineItem = 'Business - Frontier Fiber Disconnects', Amount, 0)), SUM(IF(LineItem = 'Business - Frontier Average Fiber Connections', Amount, 0))) AS f_76,
    -- Consumer - Phone Churn % = SAFE_DIVIDE([Consumer - Phone Disconnects], [Consumer - Average Phone Connections])  (Config_ID 87)
    SAFE_DIVIDE(SUM(IF(LineItem = 'Consumer - Phone Disconnects', Amount, 0)), SUM(IF(LineItem = 'Consumer - Average Phone Connections', Amount, 0))) AS f_87,
    -- Business - Phone Churn % = SAFE_DIVIDE([Business - Phone Disconnects], [Business - Average Phone Connections])  (Config_ID 88)
    SAFE_DIVIDE(SUM(IF(LineItem = 'Business - Phone Disconnects', Amount, 0)), SUM(IF(LineItem = 'Business - Average Phone Connections', Amount, 0))) AS f_88
  FROM combined_3
  GROUP BY year, month, month_date
),

tier_4 AS (
  SELECT calc.year, calc.month, calc.month_date, item.LineItem, COALESCE(item.Amount, 0) AS Amount
  FROM tier_4_calc AS calc
  CROSS JOIN last_actual_month AS l
  CROSS JOIN UNNEST(ARRAY<STRUCT<LineItem STRING, Amount FLOAT64, to_last_actual BOOL>>[
    ('Consumer - FWA Churn %', calc.f_63, TRUE),
    ('Business - FWA Churn %', calc.f_64, TRUE),
    ('Consumer - Fios Fiber Churn %', calc.f_73, TRUE),
    ('Consumer - Frontier Fiber Churn %', calc.f_74, TRUE),
    ('Business - Fios Fiber Churn %', calc.f_75, TRUE),
    ('Business - Frontier Fiber Churn %', calc.f_76, TRUE),
    ('Consumer - Phone Churn %', calc.f_87, TRUE),
    ('Business - Phone Churn %', calc.f_88, TRUE)
  ]) AS item
  -- a line item calculated from a roll forward stops where the roll forward does
  WHERE NOT item.to_last_actual OR calc.month_date <= l.max_month_date
),

tier_4_names AS (
  SELECT LineItem FROM UNNEST(ARRAY<STRING>[
    'Consumer - FWA Churn %',
    'Business - FWA Churn %',
    'Consumer - Fios Fiber Churn %',
    'Consumer - Frontier Fiber Churn %',
    'Business - Fios Fiber Churn %',
    'Business - Frontier Fiber Churn %',
    'Consumer - Phone Churn %',
    'Business - Phone Churn %'
  ]) AS LineItem
),

combined_4 AS (
  -- anti-join: a calculated line item replaces source rows with the same name (no double counting)
  SELECT c.year, c.month, c.month_date, c.LineItem, c.Amount
  FROM combined_3 AS c
  LEFT JOIN tier_4_names AS n
    ON c.LineItem = n.LineItem
  WHERE n.LineItem IS NULL
  UNION ALL
  SELECT year, month, month_date, LineItem, Amount FROM tier_4
),

output_items AS (
  -- line items whose FinalOutput is not N / NO / FALSE / 0
  SELECT LineItem FROM UNNEST(ARRAY<STRING>[
    'Consumer - Phone Gross Adds',
    'Business - Phone Gross Adds',
    'Consumer - Phone Disconnects',
    'Business - Phone Disconnects',
    'Consumer - Phone Upgrades',
    'Business - Phone Upgrades',
    'Consumer - Total Upgrades',
    'Business - Total Upgrades',
    'Consumer - FWA Gross Adds',
    'Business - FWA Gross Adds',
    'Consumer - FWA Disconnects',
    'Business - FWA Disconnects',
    'Consumer - Fios Fiber Gross Adds',
    'Consumer - Frontier Fiber Gross Adds',
    'Business - Fios Fiber Gross Adds',
    'Business - Frontier Fiber Gross Adds',
    'Consumer - Fios Fiber Disconnects',
    'Consumer - Frontier Fiber Disconnects',
    'Business - Fios Fiber Disconnects',
    'Business - Frontier Fiber Disconnects',
    'Consumer - PostPaid Gross Adds',
    'Consumer - PostPaid Disconnects',
    'Business - PostPaid Gross Adds',
    'Business - PostPaid Disconnects',
    'Consumer - Wireless Gross New Accounts',
    'Consumer - Wireless Lost Accounts',
    'Consumer - Wireless Account Splits',
    'Consumer - Wireless Account Merges',
    'Business - Wireless Gross New Accounts',
    'Business - Wireless Lost Accounts',
    'Business - Wireless Account Splits',
    'Business - Wireless Account Merges',
    'Consumer - Prepaid Phone Net Adds excl. Safelink',
    'Consumer - Prepaid Net Adds excl. Safelink',
    'Consumer - FWA Net Adds',
    'Business - FWA Net Adds',
    'Consumer - FWA Average Connections',
    'Business - FWA Average Connections',
    'Consumer - FWA Connections',
    'Business - FWA Connections',
    'Consumer - FWA Churn %',
    'Business - FWA Churn %',
    'Consumer - Fios Average Fiber Connections',
    'Consumer - Frontier Average Fiber Connections',
    'Business - Fios Average Fiber Connections',
    'Business - Frontier Average Fiber Connections',
    'Consumer - Fios Fiber Connections',
    'Consumer - Frontier Fiber Connections',
    'Business - Fios Fiber Connections',
    'Business - Frontier Fiber Connections',
    'Consumer - Fios Fiber Churn %',
    'Consumer - Frontier Fiber Churn %',
    'Business - Fios Fiber Churn %',
    'Business - Frontier Fiber Churn %',
    'Consumer - Fios Fiber Net Adds',
    'Consumer - Frontier Fiber Net Adds',
    'Business - Fios Fiber Net Adds',
    'Business - Frontier Fiber Net Adds',
    'Consumer - Phone Net Adds',
    'Business - Phone Net Adds',
    'Consumer - Average Phone Connections',
    'Business - Average Phone Connections',
    'Consumer - Phone Connections',
    'Business - Phone Connections',
    'Consumer - Phone Churn %',
    'Business - Phone Churn %',
    'Consumer - Postpaid Net Adds',
    'Business - Postpaid Net Adds',
    'Consumer - Wireless Net Accounts',
    'Business - Wireless Net Accounts'
  ]) AS LineItem
)

SELECT c.LineItem, CAST(c.year AS STRING) AS year, CAST(c.month AS STRING) AS month, COALESCE(c.Amount, 0) AS Amount
FROM combined_4 AS c
JOIN output_items AS o
  ON c.LineItem = o.LineItem
ORDER BY c.LineItem, c.month_date;
